/**
 * AI API v2 — the ONE definition of the v2 contracts. Everything else derives from it:
 *  - runtime validation (tests validate real payloads from the host against these schemas),
 *  - docs/schemas/bloodboard-api-v2.schema.json and docs/AI_API_V2_TYPES.d.ts (generated by scripts/gen-api-v2-docs.mjs at build),
 *  - the `schema` service (names listed in `V2_SCHEMA_NAMES`).
 * Change a payload → change it here first; `tests/schemas-v2.test.ts` fails when runtime and schema drift apart.
 */
import type { Schema } from './jsonschema';

const num = { type: 'number' };
const int = { type: 'integer' };
const str = { type: 'string' };
const bool = { type: 'boolean' };
const team = { enum: ['A', 'B'] };
const coord = { type: 'object', required: ['x', 'y'], properties: { x: int, y: int } };
const obj = (required: string[], properties: Record<string, unknown>, additional = true): Schema => ({ type: 'object', required, properties, additionalProperties: additional });
const arr = (items: unknown): Schema => ({ type: 'array', items });
const nullable = (s: unknown): Schema => ({ anyOf: [s as Schema, { type: 'null' }] });

const resource = obj(['status'], { status: { enum: ['available', 'used', 'exhausted', 'unavailable', 'unknown', 'unsupported'] }, count: int, note: str });
const teamResources = obj(['teamRerolls', 'bonusRerolls', 'leaderReroll', 'mascotReroll', 'apothecary', 'bribes', 'wizard', 'turnWindow', 'stars'], {
  teamRerolls: resource, bonusRerolls: resource, leaderReroll: resource, mascotReroll: resource, apothecary: resource, bribes: resource, wizard: resource, stars: resource,
  turnWindow: obj(['blitz', 'pass', 'handoff', 'foul', 'secure', 'ttm', 'bomb', 'punt', 'ktm'], { blitz: resource, pass: resource, handoff: resource, foul: resource, secure: resource, ttm: resource, bomb: resource, punt: resource, ktm: resource }),
});
const publicEvent = obj(['type', 'text'], { type: str, text: str, rule: obj(['page', 'title'], { page: int, title: str }), dice: arr(obj(['kind', 'faces'], { kind: str, faces: arr(int), block: arr(str) })) });
const publicEntry = obj(['index', 'team', 'turn', 'title', 'input', 'events', 'decisions', 'outcome'], {
  index: int, team, turn: int, title: str, input: obj(['kind'], { kind: str, playerId: str, action: str, special: str }), events: arr(publicEvent),
  decisions: arr(obj(['requestId', 'optionId', 'label', 'team'], { requestId: str, optionId: str, label: str, team })), outcome: { enum: ['completed', 'turnover', 'touchdown', 'stopped'] },
});
const player = obj(['id', 'team', 'location', 'stance', 'ma', 'st', 'ag', 'pa', 'av', 'skills', 'activated'], { id: str, team, name: str, number: int, position: str, location: str, stance: str, pos: nullable(coord), ma: int, st: int, ag: int, pa: nullable(int), av: int, skills: arr(str), activated: bool, tackleZone: bool, canBeActivated: bool });

export const observationV2 = obj(
  ['apiVersion', 'apiMinor', 'schemaVersion', 'engineVersion', 'engine', 'ruleset', 'match', 'requestId', 'revision', 'team', 'format', 'phase', 'half', 'turn', 'turnsPerHalf', 'score', 'weather', 'rerolls', 'ball', 'players', 'pitch', 'active', 'teams', 'resources', 'sinceLast', 'pending', 'activation', 'betweenTurns'],
  {
    apiVersion: { const: 2 }, apiMinor: int, schemaVersion: { const: 'bloodboard-observation/2' }, engineVersion: str,
    engine: obj(['version', 'engineHash', 'rulesHash', 'apiHash'], { version: str, engineHash: str, rulesHash: str, apiHash: str }),
    ruleset: obj(['id', 'hash', 'format', 'rulesEdition'], { rulesEdition: { enum: ['legacy', 'faq2026'] }, id: str, hash: str, format: { enum: ['standard', 'sevens'] }, variant: str, rules: {} }),
    match: obj(['matchId', 'kind', 'mirror', 'half', 'drive', 'stateRevision', 'historyLength'], { matchId: nullable(str), kind: nullable(str), mirror: bool, half: int, drive: nullable(int), stateRevision: str, historyLength: int }),
    requestId: int, revision: str, team, format: { enum: ['standard', 'sevens'] }, phase: str, half: int, turn: obj(['A', 'B'], { A: int, B: int }), turnsPerHalf: int,
    score: obj(['A', 'B'], { A: int, B: int }), weather: str, rerolls: obj(['A', 'B'], { A: int, B: int }),
    ball: obj(['kind'], { kind: { enum: ['held', 'ground', 'none'] } }), players: arr(player),
    pitch: obj(['width', 'height', 'w', 'h', 'wideRows', 'endZone', 'losColumn'], { width: int, height: int, w: int, h: int, wideRows: int, endZone: obj(['A', 'B'], { A: int, B: int }), losColumn: obj(['A', 'B'], { A: int, B: int }) }),
    active: team, kicking: nullable(team), drive: nullable(int),
    teams: obj(['A', 'B'], { A: obj(['name', 'score', 'turn', 'rerolls'], { name: str, score: int, turn: int, rerolls: int }), B: obj(['name', 'score', 'turn', 'rerolls'], { name: str, score: int, turn: int, rerolls: int }) }),
    resources: obj(['A', 'B'], { A: teamResources, B: teamResources }),
    sinceLast: obj(['from', 'to', 'entries'], { from: int, to: int, entries: arr(publicEntry) }),
    pending: nullable(obj(['requestId', 'type', 'team', 'prompt', 'options'], { requestId: str, type: str, team, prompt: str, options: arr(obj(['id', 'label'], { id: str, label: str })) })),
    activation: nullable(obj(['playerId', 'action'], { playerId: str, action: str })), betweenTurns: bool,
    contextInfo: obj(['present', 'bytes', 'maxBytes', 'schema', 'resetReason'], { present: bool, bytes: int, maxBytes: int, schema: nullable(str), resetReason: nullable(obj(['code'], { code: str, detail: str })) }),
    coachContext: {}, hostExtensions: {}, strategicPublic: {},
  },
);

const paramDef = obj(['name', 'kind', 'required'], { name: str, kind: { enum: ['player', 'square', 'path', 'flag', 'enum'] }, required: bool, domain: { enum: ['opponent', 'teammate', 'any'] }, values: arr(str), note: str });
const choice = obj(['type', 'owner', 'label', 'actors', 'skeleton', 'params', 'targetQueries', 'timing', 'continuation', 'enabled'], {
  type: str, owner: team, label: str, actors: arr(obj(['playerId', 'enabled'], { playerId: str, enabled: bool, reason: str })), skeleton: { type: 'object' }, params: arr(paramDef),
  targetQueries: arr(obj(['param', 'service', 'args'], { param: str, service: { const: 'legalTargets' }, args: { type: 'object' } })), path: obj(['allowed'], { allowed: bool }), cost: str, timing: str, continuation: str, enabled: bool, reason: str,
  options: arr(obj(['id', 'label'], { id: str, label: str, detail: str })),
});
export const legalChoices = obj(['ok', 'schema', 'node', 'owner', 'phase', 'choices', 'coverage', 'position'], {
  ok: { const: true }, schema: { const: 'bloodboard-legal-choices/1' }, node: { enum: ['action', 'decision', 'setup', 'transition', 'terminal'] }, owner: nullable(team), phase: str, choices: arr(choice),
  coverage: obj(['complete', 'derivedFrom', 'notes'], { complete: bool, derivedFrom: str, notes: arr(str) }), position: str,
});
export const legalTargets = obj(['ok', 'choice', 'param', 'values', 'total', 'offset', 'complete', 'next', 'coverage', 'position'], {
  ok: { const: true }, choice: str, param: str, values: arr(obj(['value', 'legal'], { value: { anyOf: [str, coord] }, legal: bool, reason: str })), total: int, offset: int, complete: bool, next: nullable(int), coverage: str, position: str,
});
const branch = obj(['index', 'p', 'label'], { index: int, p: num, label: str, faces: arr(int), detail: str, id: str });
export const forkNode = { anyOf: [
  obj(['ok', 'fork', 'node', 'depth', 'p', 'dice', 'branches', 'unresolvedMass', 'exact', 'events'], { ok: { const: true }, fork: str, from: str, parent: nullable(str), node: { const: 'chance' }, depth: int, p: num, dice: arr(int), display: nullable(str), rolledBy: nullable(team), branches: arr(branch), unresolvedMass: num, exact: bool, events: arr(obj(['type', 'text'], { type: str, text: str })), howToContinue: str, revisionBound: bool }),
  obj(['ok', 'fork', 'node', 'depth', 'p', 'decisionOf', 'requestId', 'branches', 'defaultBranch', 'events'], { ok: { const: true }, fork: str, from: str, parent: nullable(str), node: { const: 'decision' }, depth: int, p: num, decisionOf: team, requestId: str, type: str, prompt: str, branches: arr(branch), defaultBranch: int, events: arr(obj(['type', 'text'], { type: str, text: str })), howToContinue: str, revisionBound: bool }),
  obj(['ok', 'fork', 'node', 'depth', 'p', 'completed', 'turnover', 'touchdown', 'events', 'position'], { ok: { const: true }, fork: str, from: str, parent: nullable(str), node: { const: 'terminal' }, depth: int, p: num, completed: bool, turnover: bool, touchdown: nullable(team), events: arr(obj(['type', 'text'], { type: str, text: str })), position: nullable(str), howToContinue: str, revisionBound: bool }),
] } as Schema;
export const receipt = obj(['schema', 'requestId', 'accepted', 'input', 'source', 'revisionBefore', 'revisionAfter', 'historyFrom', 'historyTo', 'entries', 'outcome', 'scoreAfter'], {
  schema: { const: 'bloodboard-receipt/1' }, requestId: nullable(int), accepted: bool, input: nullable({ type: 'object' }), source: obj(['coach', 'via', 'fellBack', 'reason'], { coach: str, via: str, fellBack: bool, reason: nullable(str) }),
  revisionBefore: str, revisionAfter: str, historyFrom: int, historyTo: int, entries: arr(publicEntry), outcome: nullable({ enum: ['completed', 'turnover', 'touchdown', 'stopped'] }), scoreAfter: obj(['A', 'B'], { A: int, B: int }), error: str,
});
const violation = obj(['level', 'code', 'text'], { level: { enum: ['error', 'warning'] }, code: str, text: str });
export const rosterRequest = obj(['format', 'play', 'mode', 'rosters'], { format: { enum: ['standard', 'sevens'] }, play: { enum: ['exhibition', 'tournament'] }, budget: int, mode: { enum: ['blind', 'sequential'] }, opponentRoster: nullable(str), rosters: arr(obj(['id', 'name', 'draftable', 'positions'], { id: str, name: str, leagues: arr(str), draftable: bool, positions: arr({ type: 'object' }) })) });
export const buildRequest = obj(['rosterId', 'format', 'play', 'budget', 'roster', 'template', 'builtinTeam'], { rosterId: str, format: { enum: ['standard', 'sevens'] }, play: str, budget: int, roster: { type: 'object' }, template: { type: 'object' }, builtinTeam: nullable({ type: 'object' }), attempt: int, previousViolations: arr(violation) });
export const setupRequestV2 = obj(['defaultPositions', 'fieldedIds', 'legalSquares', 'lineOfScrimmage', 'minLine', 'maxWide', 'pitch', 'format', 'fielding'], {
  defaultPositions: { type: 'object' }, fieldedIds: arr(str), fixedPlayerIds: arr(str), legalSquares: arr(coord), lineOfScrimmage: int, centreRows: { type: 'object' }, minLine: int, allOnLine: bool, maxWide: int, wideRows: int, pitch: obj(['w', 'h'], { w: int, h: int }), format: str,
  fielding: obj(['mode', 'count', 'candidates', 'mustField'], { mode: { enum: ['fixed', 'free'] }, count: int, candidates: arr(obj(['id', 'number', 'position', 'onPitch'], { id: str, number: int, position: str, onPitch: bool })), mustField: arr(str) }),
  attempt: int, previousErrors: arr(str),
});
export const kickRequest = obj(['receiving', 'kickerCandidates', 'legalSquares', 'kickDistance', 'pitch'], { receiving: team, kickerCandidates: arr(obj(['id', 'number', 'position', 'skills', 'hasKick'], { id: str, number: int, position: str, skills: arr(str), hasKick: bool })), legalSquares: arr(coord), kickDistance: { enum: ['d6', 'lowerOf2d6'] }, pitch: obj(['w', 'h'], { w: int, h: int }), defaultAnswer: obj(['kicker', 'target', 'useKick'], { kicker: str, target: coord, useKick: bool }), attempt: int, previousErrors: arr(str) });

export const V2_SCHEMAS: Record<string, Schema> = { observationV2, legalChoices, legalTargets, forkNode, receipt, rosterRequest, buildRequest, setupRequestV2, kickRequest };
export const V2_SCHEMA_NAMES = Object.keys(V2_SCHEMAS);
